import {observe} from '@github/selector-observer'
import pageFocused from './github/page-focused'
import {remoteForm} from '@github-ui/remote-form'

// By default the oauth button remains disabled until the visitor focusses the
// window. This event handler enables the button once the window has been focussed.
async function updateButtonOnPageFocused(button: Element) {
  await pageFocused(document)
  await new Promise(resolve => setTimeout(resolve, 1000))
  if (button instanceof HTMLButtonElement) button.disabled = false
}

function unclickableEvent(event: Event) {
  event.preventDefault()
}

async function enableManualRedirect(link: Element) {
  link.addEventListener('click', unclickableEvent)
  link.classList.add('color-fg-muted')

  await new Promise(resolve => setTimeout(resolve, 3000))

  link.classList.remove('color-fg-muted')
  link.removeEventListener('click', unclickableEvent)
}

observe('.js-authorization-buttons .js-oauth-authorize-btn', authorizeButton => {
  updateButtonOnPageFocused(authorizeButton)
})

observe('#js-manual-authorize-redirect', manualAuthorizeLink => {
  enableManualRedirect(manualAuthorizeLink)
})

remoteForm('.js-toggler-container .js-set-approval-state', async function (form, wants) {
  const container = form.closest('.js-toggler-container')!
  container.classList.add('loading')
  const response = await wants.json()
  if (response.json.approval_state === 'approved') {
    container.classList.add('on')
  } else if (response.json.approval_state === 'denied') {
    container.classList.add('revoked')
    container.classList.remove('on')
  }
  container.classList.remove('loading')
})

// Settings -> Applications -> Organization access -> "Request access" button
remoteForm('.js-request-access-approval-form', async function (form, wants) {
  await wants.text()
  const id = form.getAttribute('data-container-id')!
  document.querySelector(`#${id}`)!.classList.add('on')
})
